-- Vibe Tropical: esquema inicial. Valores em numeric(12,2). Acesso só para a proprietária (profiles.role = 'owner').
create table profiles (id uuid primary key references auth.users on delete cascade, full_name text, role text not null default 'owner' check (role='owner'), created_at timestamptz not null default now());
create function is_owner() returns boolean language sql security definer stable set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and role='owner') $$;
create table settings (id int primary key default 1 check (id=1), business_name text default 'Vibe Tropical', logo_url text, whatsapp text, address text default 'Marituba-PA', opening_hours text default '14:00 às 19:00', default_delivery_fee numeric(12,2) check (default_delivery_fee>=0));
insert into settings(id) values (1);
create table products (id uuid primary key default gen_random_uuid(), name text not null, description text, photo_url text, category text, active boolean not null default true, created_at timestamptz not null default now());
create table product_variants (id uuid primary key default gen_random_uuid(), product_id uuid not null references products on delete cascade, size_ml int not null check (size_ml>0), price numeric(12,2) not null check (price>=0), stock_qty int not null default 0 check (stock_qty>=0), min_qty int not null default 0 check (min_qty>=0), active boolean not null default true, unique(product_id,size_ml));
create table customers (id uuid primary key default gen_random_uuid(), name text not null, phone text, address text, notes text, created_at timestamptz not null default now());
create table orders (id uuid primary key default gen_random_uuid(), order_number bigint generated always as identity, customer_id uuid references customers, customer_name text not null, phone text, service_type text not null check (service_type in ('retirada','entrega')), status text not null default 'aguardando' check (status in ('aguardando','confirmado','preparacao','saiu','entregue','cancelado')), address text, delivery_fee numeric(12,2) not null default 0 check (delivery_fee>=0), payment_method text, notes text, created_at timestamptz not null default now());
create table order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references orders on delete cascade, variant_id uuid references product_variants, product_name text not null, size_ml int not null, unit_price numeric(12,2) not null check (unit_price>=0), quantity int not null check (quantity>0));
create table sales (id uuid primary key default gen_random_uuid(), sale_number bigint generated always as identity, origin text not null check (origin in ('presencial','whatsapp')), status text not null default 'confirmada' check (status in ('pendente','confirmada','cancelada')), payment_method text not null check (payment_method in ('dinheiro','pix','credito','debito')), subtotal numeric(12,2) not null check (subtotal>=0), delivery_fee numeric(12,2) not null default 0, total numeric(12,2) not null check (total>=0), order_id uuid unique references orders, customer_id uuid references customers, created_at timestamptz not null default now());
create table sale_items (id uuid primary key default gen_random_uuid(), sale_id uuid not null references sales on delete cascade, variant_id uuid references product_variants, product_name text not null, size_ml int not null, unit_price numeric(12,2) not null check (unit_price>=0), quantity int not null check (quantity>0));
create table expense_categories (id uuid primary key default gen_random_uuid(), name text not null unique);
insert into expense_categories(name) values ('Compra de frutas'),('Ingredientes'),('Embalagens'),('Transporte'),('Combustível'),('Entregas'),('Energia'),('Água'),('Outros');
create table expenses (id uuid primary key default gen_random_uuid(), description text not null, category_id uuid references expense_categories, amount numeric(12,2) not null check (amount>0), expense_date date not null default current_date, payment_method text, note text, created_at timestamptz not null default now());
create table stock_movements (id uuid primary key default gen_random_uuid(), variant_id uuid not null references product_variants, kind text not null check (kind in ('producao','venda','estorno','perda','descarte')), quantity int not null check (quantity>0), sale_id uuid references sales, note text, created_at timestamptz not null default now());
create table cash_closings (id uuid primary key default gen_random_uuid(), closing_date date not null unique, cash_sales numeric(12,2) not null, pix_sales numeric(12,2) not null, card_sales numeric(12,2) not null, cash_expenses numeric(12,2) not null, other_expenses numeric(12,2) not null, expected_cash numeric(12,2) not null, counted_cash numeric(12,2) not null, difference numeric(12,2) not null, note text, created_at timestamptz not null default now());
create index on sales(created_at); create index on sales(status); create index on expenses(expense_date); create index on orders(status); create index on stock_movements(variant_id,created_at); create index on order_items(order_id); create index on sale_items(sale_id);
do $$ declare t text; begin foreach t in array array['profiles','settings','products','product_variants','customers','orders','order_items','sales','sale_items','expense_categories','expenses','stock_movements','cash_closings'] loop
  execute format('alter table %I enable row level security', t);
  execute format('create policy owner_all on %I for all using (is_owner()) with check (is_owner())', t); end loop; end $$;
create policy self_read on profiles for select using (id=auth.uid());
